import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

public class BuildPeriod {
    public void build(@Val PeriodRequest request, @Val Sheet sheet, Out<Period> period) {
        period.set(new Period(sheet.id(), request.name(), LocalDate.parse(request.from()), LocalDate.parse(request.to()),
                request.cap().isEmpty() ? null : Integer.valueOf(request.cap())));
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.plugin.variable.Val;

/** Refuses a period whose name another period on the sheet already has (ignoring case), or whose dates overlap another's. */
public class CheckPeriodFits {
    public void check(@Val Period period, PeriodRepository repository) throws InvalidPeriodException {
        for (Period other : repository.findAll(period.sheetId())) {
            if (other.name().equalsIgnoreCase(period.name())) {
                throw new InvalidPeriodException("The name " + period.name() + " is already in use.");
            }
            if (other.overlaps(period)) {
                throw new InvalidPeriodException("The dates overlap the period " + other.name() + ".");
            }
        }
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.plugin.variable.Val;

public class SaveGeneratedPeriods {
    public void save(@Val GeneratedPeriods generated, PeriodRepository repository) {
        generated.periods().forEach(repository::insert);
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Records each generated period as added, earliest first, in the form a period added by hand takes. */
public class AuditGeneratedPeriods {
    public void audit(@Val GeneratedPeriods generated, @RequestParam("user") String user, Audit audit) {
        for (Period period : generated.periods()) {
            audit.record("PERIOD_ADDED sheet=" + period.sheetId() + " by=" + user + " period=" + period.name()
                    + " from=" + period.from() + " to=" + period.to());
        }
    }
}

